//! Static Imagine skill-id -> `(name, icon)` table, and the icon basenames
//! it references, compiled into the executable via `include_bytes!`.
//!
//! Generated by `scripts/gen-imagine-table.py` from the hand-curated
//! `crates/app/data/imagine_table.json`, itself derived from the game
//! client via BPSR-ZDPS; see `THIRD_PARTY_NOTICES.md`. Do not edit by hand.
//!
//! // IMAGINE-TAKEDOWN: not one of the five marked sites — this module is
//! // removed via `rm`, not edited in place. See `docs/plans/*imagines-plan.md`
//! // D4. Takedown removes this module, `crates/app/assets/imagines/`,
//! // `crates/app/data/imagine_table.json`, `scripts/prep-imagine-icons.py`,
//! // `scripts/gen-imagine-table.py`, and the five marked sites. Since the
//! // icons are compiled in (issue #123), an already-distributed copy needs
//! // a source deletion, rebuild, and re-release, not a directory deletion.
//!
//! Coverage is a hand-curated allowlist, not every skill id in the game —
//! an id outside the 106 curated Imagines yields `None` from
//! `imagine_of_skill_id`, and callers must treat that as "not an Imagine",
//! never as a lookup failure to surface.

/// One equippable Imagine's display data.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Imagine {
    pub name: &'static str,
    pub icon: &'static str,
}

/// Look up the Imagine a skill id belongs to, if `id` is one of the 106
/// curated ids. An id outside that set (including every excluded id in
/// `crates/app/data/imagine_table.json`'s `_excluded`) yields `None` —
/// that is the mechanism by which non-Imagine skill ids are dropped
/// rather than mis-rendered as a slot.
///
/// `name` is always the *canonical* (39xx) name for the id's icon, not
/// necessarily the id's own raw `SkillTable.json` name: identity is the
/// icon basename, not the name (spec's "Many-to-one is expected"). A
/// variant id whose own name disagrees with its canonical row (e.g.
/// `102651`'s raw name is "Boar Knight", but it shares an icon with
/// the canonical `3905` "Stunt! Boarrier Rush" and resolves to that
/// name here) must resolve to the canonical name — deduping by an id's
/// own raw name would let one equipped Imagine occupy both of a
/// player's two slots.
