/// Generates `IMAGINE_ICON_FILES` (every icon basename referenced by
/// `imagine_of_skill_id`) and `IMAGINE_ICON_BYTES` (each of those
/// basenames paired with its PNG, compiled in via `include_bytes!`)
/// from one literal list, so the two cannot silently disagree. Mirrors
/// `class_icons!` in `icons.rs`, but without an exhaustive match — the
/// key set is an open-ended game-data id, not a small fixed enum, so
/// there is no "missing variant" compile-time guarantee to buy.
/// `IMAGINE_ICON_FILES` is `#[cfg(test)]`-gated: production code only
/// needs `IMAGINE_ICON_BYTES` (which pairs each basename with its
/// bytes), so the basename-only list would otherwise be dead code in a
/// release build. `icons.rs`'s tests reference it across the module
/// boundary, which is fine — `cfg(test)` applies crate-wide under
/// `cargo test`, so both sides see it.
macro_rules! imagine_icons {
    ($($name:literal),+ $(,)?) => {
        #[cfg(test)]
        pub const IMAGINE_ICON_FILES: &[&str] = &[$($name),+];
        pub const IMAGINE_ICON_BYTES: &[(&str, &[u8])] = &[
            $(( $name, include_bytes!(concat!("../assets/imagines/", $name, ".png")) )),+
        ];
    };
}
