#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn entry_count_is_106() {
        assert_eq!(ALL_ENTRIES.len(), 106);
    }

    #[test]
    fn distinct_name_and_icon_counts() {
        let names: HashSet<&str> = ALL_ENTRIES.iter().map(|(_, name, _)| *name).collect();
        let icons: HashSet<&str> = ALL_ENTRIES.iter().map(|(_, _, icon)| *icon).collect();
        assert_eq!(names.len(), 84);
        assert_eq!(icons.len(), 81);
    }

    #[test]
    fn every_all_entries_icon_is_in_icon_files() {
        let files: HashSet<&str> = IMAGINE_ICON_FILES.iter().copied().collect();
        for (_, _, icon) in ALL_ENTRIES {
            assert!(
                files.contains(icon),
                "icon {icon} referenced by ALL_ENTRIES but missing from IMAGINE_ICON_FILES"
            );
        }
    }

    #[test]
    fn icon_files_len_is_81() {
        assert_eq!(IMAGINE_ICON_FILES.len(), 81);
    }

    #[test]
    fn many_to_one_group_resolves_to_the_same_imagine() {
        // Spec's "Many-to-one is expected — identity is the icon basename":
        // these five ids are tier/class variants of the same Boar Imagine.
        // `102651` and `102655` have their own, divergent raw names in
        // SkillTable.json ("Boar Knight", "Boar Impact!"), but
        // `imagine_of_skill_id` must resolve every one of them to the
        // *canonical* (39xx) name and icon — otherwise a Boar player
        // equipping a variant id would read as two different Imagines and
        // occupy both of their two slots.
        let canonical = imagine_of_skill_id(3905).unwrap();
        assert_eq!(canonical.name, "Stunt! Boarrier Rush");
        for id in [3905, 102640, 102651, 102655, 102658] {
            assert_eq!(imagine_of_skill_id(id).unwrap(), canonical);
        }
    }

    #[test]
    fn another_variant_resolves_to_its_canonical_name() {
        // `2002840`'s own raw name is "Arcane! Swift Vortex"; its icon's
        // canonical (39xx) name is "Arcane! Meteor Shower".
        assert_eq!(
            imagine_of_skill_id(2_002_840).unwrap().name,
            "Arcane! Meteor Shower"
        );
    }

    #[test]
    fn spot_check_a_known_entry() {
        let imagine = imagine_of_skill_id(3905).unwrap();
        assert_eq!(imagine.name, "Stunt! Boarrier Rush");
        assert_eq!(imagine.icon, "skill_aoyi_skill_icon_001");
    }

    #[test]
    fn excluded_and_unknown_ids_are_none() {
        // Every spec-excluded id (docs/specs/2026-08-17-issue-33-imagines-spec.md
        // "Curation") plus an arbitrary id that was never in SkillTable.json.
        for id in [
            3000,
            3601,
            706103,
            4310,
            102659,
            2350,
            2351,
            2900270,
            2900370,
            2900570,
            999_999_999,
        ] {
            assert_eq!(imagine_of_skill_id(id), None);
        }
    }
}
